def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    temp = ""

    # Handle potential invalid inputs
    if not isinstance(paren_string, str) or " " in paren_string:
        raise ValueError("Invalid input. Input should be a string without spaces and balanced groups of parentheses.")

    for char in paren_string:
        # Initialize a flag to check if we need to reverse back to the previous opening brace
        reversal_flag = False

        # Check if it's an opening brace
        if char == "(":
            reversal_flag = True
            temp += char
        # If it's a closing brace, add it to the temporary string and handle reversals
        elif char == ")":
            temp += char
            if reversal_flag:
                result.pop()
            else:
                result.append(temp)
                temp = ""

    return result

