def cantor_numbering(N: int) -> str:
    if N <= 0:
        raise ValueError("Position must be a positive integer.")

    if N == 1:
        return "1/1"

    row, col = N, 1
    while True:
        if row % 2 == 1 and col % 2 == 0:
            return f"{col}/{row}"
        elif row % 2 == 0 and col % 2 == 1:
            return f"{row}/{col}"
        elif row == 1 or col == 1:
            return f"{row}/{col}"
        row //= 2
        col //= 2

def max_product(num_str: str, N: int, K: int) -> int:
    if N == 0 or K == 0:
        return 0

    num = int(num_str)

    if K == 1:
        # The maximum product is obtained by inserting one multiplication sign at the beginning or end of the string
        return num * int(num_str[1:-1])

    max_product = -float('inf')
    for i in range(1, N - K + 2):
        left = int(num_str[:i])
        right = int(num_str[i:])
        product = left * right
        if product > max_product:
            max_product = product

    return max_product

