def verify_isbn(isbn: str) -> str:
    if len(isbn) != 12 and isbn != 'X':
        return "Error: The ISBN number must be exactly 12 digits."

    # Remove any '-' character
    isbn = isbn.replace('-', '')

    # Calculate the correct ISBN checksum
    def calculate_isbn_checksum(isbn):
        if isbn.endswith('X'):
            isbn = isbn[:-1] + '10'
        total = sum((int(digit) or 10) * (2 ** index) for index, digit in enumerate(reversed(isbn)))
        return str((total % 11) % 11).upper()

    calculated_checksum = calculate_isbn_checksum(isbn)

    if calculated_checksum == isbn[11]:
        return "Right"
    else:
        corrected_isbn = isbn[:-1] + calculated_checksum
        return corrected_isbn

