def max_energy(beads):
    n = len(beads)
    dp = [0] * (n + 1)

    for i in range(1, n + 1):
        for j in range(i):
            if beads[j] == beads[i - 1]:
                dp[i] = max(dp[i], dp[j] * beads[i] * beads[j + 1])

    return dp[n]

