def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if n < 0 or not coeffs:
        return "Invalid input, need n >= 0 and non-empty coeffs list."

    result = []
    for i in range(n, -1, -1):
        coeff = coeffs[i]
        if coeff == 0:
            continue

        sign = "+" if coeff > 0 else "-"
        coeff_abs = abs(coeff)

        if coeff_abs == 1 and i == n:  # Constant term
            result.append("x")
        elif coeff_abs == 1 and i == 0:  # All-zero coefficients
            continue
        elif coeff_abs == 1:
            result.append(f"x^{i}")
        elif i == n:
            result.append(f"{sign}{coeff_abs}")
        else:
            result.append(f"{sign}{coeff_abs}x^{i}")

    return "".join(result)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(message) != len(encoded):
        return "Failed"

    mapping = {}

    try:
        for encoded_index, original_index in enumerate(original):
            if encoded_index != original_index:
                if encoded[encoded_index] not in mapping:
                    mapping[encoded[encoded_index]] = original[original_index]
                elif mapping[encoded[encoded_index]] != original[original_index]:
                    return "Failed"
    except IndexError:
        return "Failed"

    if len(mapping) != len(original):
        return "Failed"

    decoded_message = ""

    try:
        for character in message:
            if character in mapping:
                decoded_message += mapping[character]
            else:
                return "Failed"
    except KeyError:
        return "Failed"

    return decoded_message

import math

def largest_prime_factor(n: int) -> int:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    largest_factor = -1
    # Check for the smallest prime factor (2)
    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    # Check for odd factors from 3 to sqrt(n)
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i

    # If 'n' is a prime number greater than 2
    if n > 2:
        largest_factor = n

    return largest_factor

def count_partitions(n: int, k: int, x: int) -> int:
    # Handle edge cases where n is less than k or k is less than 1
    if n < k or k < 1:
        return 0

    # Helper function to calculate combination of n taken k at a time
    def combination(n, k):
        if k > n // 2:
            k = n - k
        result = 1
        for i in range(1, k + 1):
            result *= n - i + 1
            result //= i
        return result

    # Calculate number of partitions considering the minimum part requirement
    total_partitions = 0
    for i in range(x, n + 1):
        remaining_sum = n - i
        remaining_parts = k - 1
        total_partitions += combination(remaining_sum, remaining_parts) * combination(i - 1, i - k)

    return total_partitions

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]

    if last > n:
        return 0
    if last == n:
        return 2

    # Avoid calculating the same subproblem multiple times
    return sum(count_sequences(n, i, memo) for i in range(1, last // 2 + 1))

