def generate_numbers(n: int, rules: List[tuple]) -> int:
    def transform(n):
        return tuple(int(d) for d in str(n))

    queue = deque([n])
    visited = set()
    visited.add(n)
    count = 0

    while queue:
        current = queue.popleft()
        if current in visited:
            continue
        visited.add(current)
        count += 1
        transformations = transform(current)
        for transformation in transformations:
            if transformation in visited:
                continue
            queue.append(transformation)

    return count

