def calculate_score(system: int, points: str) -> list:
    scores = []
    W_count, L_count = points.count('W'), points.count('L')
    total_points = W_count + L_count
    played_game = True

    while played_game:
        if total_points >= system:
            if (W_count - L_count >= 2) or (L_count - W_count >= 2):
                scores.append(f"{W_count}:{L_count}")
                break
            else:
                total_points -= system
                played_game = True
        else:
            result = W_count if W_count > L_count else L_count
            scores.append(f"{result}:{result}")
            played_game = False

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    # Base case: C(0) is 1
    if n == 0:
        return 1
    # Initialize the list to store intermediate results
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]
    return catalan[n]

